style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
/* Change the main background image */
  body {
    background-image: url("https://i.imgur.com/YOUR_IMAGE_LINK.jpg");
    background-size: cover;
    background-repeat: no-repeat;
    background-attachment: fixed;
    background-position: center;
  }

  /* Make background visible by removing white panels */
  .container-main,
  .content,
  .game-home-page,
  .profile-container,
  .game-card-container {
    background: rgba(255, 255, 255, 0.8) !important;
    border-radius: 10px;
    padding: 10px;
  }

  /* Optional: Make the header semi-transparent */
  .navbar-fixed-top {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }

  /* Optional: Change text color for contrast */
  body, h1, h2, h3, h4, h5, h6, p, span, div {
    color: #000 !important;
  }
}
